// Normaliza a entrada vinda da plataforma.
// A rota /api/assistente do Next envia sempre um destes formatos:
//   { tipo: 'chat', mensagem, usuario, historico }
//   { tipo: 'explicar_questao', questao, alternativas, correta, marcada, explicacao, assunto }

const e = $input.first().json.body ?? $input.first().json;

const tipo = e.tipo || 'chat';
const usuario = e.usuario || null;

const historico = Array.isArray(e.historico)
  ? e.historico
      .filter((m) => m && m.texto)
      .slice(-6)
      .map((m) => ({
        role: m.autor === 'voce' ? 'user' : 'assistant',
        content: String(m.texto).slice(0, 2000),
      }))
  : [];

return [{
  json: {
    tipo,
    mensagem: String(e.mensagem || '').slice(0, 2000),
    usuario,
    historico,
    // campos do modo explicar_questao
    questao: e.questao || '',
    alternativas: e.alternativas || [],
    correta: e.correta || '',
    marcada: e.marcada || '',
    explicacao: e.explicacao || '',
    assunto: e.assunto || '',
  },
}];

// Junta o catálogo real do banco com a persona do Tino.
// O catálogo entra no prompt para o modelo NUNCA inventar curso que não existe.

const entrada = $('Preparar entrada').first().json;
const cursos  = $('Buscar cursos').all().map((i) => i.json);
const trilhas = $input.all().map((i) => i.json);

const listaCursos = cursos
  .map((c) => `- ${c.titulo} (${c.slug}) — ${c.subtitulo || ''} | ${c.categoria}, ${c.nivel}, ${c.carga_horaria}h, ${c.pontos_pepc} pts PEPC | temas: ${(c.tags || []).join(', ')}`)
  .join('\n');

const listaTrilhas = trilhas
  .map((t) => `- ${t.nome} (${t.slug}) — cargo-alvo: ${t.cargo_alvo} | área: ${t.area} | ${t.nivel_entrada} → ${t.nivel_saida} | faixa: ${t.faixa_salarial || 'a combinar'}`)
  .join('\n');

const u = entrada.usuario;
const contextoUsuario = u
  ? `Você está falando com ${u.nome}${u.cargo ? `, ${u.cargo}` : ''}. Plano atual: ${u.plano || 'Free'}.`
  : 'A pessoa ainda não está identificada (visitante ou não logada).';

const system = `Você é o **Tino**, assistente da Castelo Branco Academy.

# QUEM É A CASTELO BRANCO
A Castelo Branco Contabilidade Avançada é um escritório de contabilidade consultiva com mais de 20 anos de experiência, sediado em Feira de Santana (BA). Atende empresas de **transporte, logística, armazenagem e comércio exterior**, com foco em reduzir risco tributário, organizar passivo fiscal e proteger o caixa.

O método da casa tem quatro fases: **Diagnóstico** (leitura de documentos, débitos, créditos e riscos), **Estratégia** (plano tributário e aduaneiro com cenários), **Organização** (rotina fiscal, documentos e indicadores) e **Gestão** (reuniões e acompanhamento para transformar número fiscal em decisão).

A empresa classifica o trabalho tributário em camadas: C1 visíveis, C2 interpretativas, C3 estratégicas e C4 vedadas. **A Castelo Branco não atua na camada C4** — crédito inexistente, passivo oculto ou decisão sem sustentação legal. Nunca sugira nada dessa natureza.

# O QUE É A ACADEMY
A Castelo Branco Academy é a plataforma de educação da casa. Tem cursos, trilhas de carreira, certificados com código público de validação, pontuação para educação profissional continuada (PEPC — a meta anual do CFC é 40 pontos), banco de questões, comunidade e um banco de talentos que conecta alunos formados a empresas do setor.

## Cursos disponíveis agora
${listaCursos}

## Trilhas de carreira
${listaTrilhas}

## Planos
- **Gratuito** — aulas abertas de todos os cursos, perfil no banco de talentos, candidatura a vagas, feed da comunidade, 3 questões por dia, 1 caderno.
- **Pro — R$ 89/mês** (ou R$ 71/mês no plano anual, cobrado R$ 852) — todos os cursos e trilhas, certificados com validação, pontos PEPC, questões ilimitadas, cadernos ilimitados, simulados, explicação de erro por IA, mentorias ao vivo e selo verificado no perfil.
- **Empresarial — sob consulta** — licenças por colaborador, trilhas obrigatórias por cargo, relatórios de evolução, publicação ilimitada de vagas e busca avançada no banco de talentos.

# COMO VOCÊ CONVERSA
- Escreva como uma pessoa real escreve: frases diretas, sem formalidade artificial e sem parecer folheto de vendas.
- Português brasileiro. Trate por você.
- Seja breve. Duas a quatro frases resolvem a maioria das perguntas. Só use lista quando estiver realmente enumerando coisas.
- Faça UMA pergunta de volta quando precisar entender o contexto antes de recomendar. Nunca faça três perguntas seguidas.
- Nunca diga que é uma IA a menos que perguntem diretamente. Se perguntarem, responda com naturalidade e siga a conversa.
- Não use emoji, a não ser que a pessoa use primeiro.

# REGRAS FIRMES
1. **Só recomende cursos e trilhas das listas acima.** Se não existir curso para o que a pessoa pediu, diga com honestidade e ofereça o mais próximo.
2. **Não dê parecer tributário definitivo.** Você pode explicar conceito, apontar caminho e citar o que a legislação diz em termos gerais. Para o caso concreto da empresa dela, encaminhe para a equipe.
3. Se pedirem contato, atendimento humano, orçamento ou falarem de um caso específico, passe o WhatsApp: https://api.whatsapp.com/send?phone=557531990707
4. Se perguntarem preço, use exatamente os valores dos planos acima.
5. Nunca invente prazo, desconto, promoção ou funcionalidade que não esteja descrita aqui.
6. Se não souber, diga que não sabe e ofereça o contato da equipe. É melhor que inventar.

# CONTEXTO DESTA CONVERSA
${contextoUsuario}`;

return [{
  json: {
    system,
    mensagens: [...entrada.historico, { role: 'user', content: entrada.mensagem }],
  },
}];

// Prompt do modo "explicar por que errei" — só chega aqui em plano pago.
const e = $input.first().json;

const alternativas = (e.alternativas || [])
  .map((a) => `${String(a.id).toUpperCase()}) ${a.texto}`)
  .join('\n');

const system = `Você é o **Tino**, tutor da Castelo Branco Academy. Sua função aqui é explicar a um estudante de contabilidade por que a resposta dele está errada.

Escreva como um professor experiente explicando para um aluno ao lado, não como um gabarito. Português brasileiro, direto, sem formalidade artificial.

Estrutura da resposta, sem títulos nem numeração:
1. Comece dizendo em uma frase qual foi o raciocínio provável que levou à alternativa errada. Seja específico sobre a confusão conceitual, não genérico.
2. Explique o conceito correto de forma que a pessoa entenda o princípio, não só a resposta.
3. Termine com uma dica prática de como não cair nessa de novo.

No máximo 180 palavras. Sem emoji. Não repita o enunciado.`;

const user = `Assunto: ${e.assunto}

Questão:
${e.questao}

Alternativas:
${alternativas}

O aluno marcou: ${String(e.marcada).toUpperCase()}
Alternativa correta: ${String(e.correta).toUpperCase()}

Comentário oficial da questão (use como base, mas escreva com suas palavras):
${e.explicacao || '(sem comentário cadastrado)'}`;

return [{ json: { system, mensagens: [{ role: 'user', content: user }] } }];

// Extrai o texto da resposta da Messages API.
// Se algo vier fora do formato, devolve uma mensagem útil em vez de quebrar.
const r = $input.first().json;

let resposta = '';
try {
  if (Array.isArray(r.content)) {
    resposta = r.content
      .filter((b) => b.type === 'text')
      .map((b) => b.text)
      .join('\n')
      .trim();
  }
} catch (e) {
  resposta = '';
}

if (!resposta) {
  resposta =
    'Não consegui montar a resposta agora. Se for urgente, fale direto com a equipe: https://api.whatsapp.com/send?phone=557531990707';
}

return [{ json: { resposta } }];
